#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum RemoteNetworkMode {
    Off,
    LocalNetwork,
    Tailscale,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub enum RemoteRestartPolicy {
    /// Enabling a listener is process-scoped. A new `RemoteGatewayState` never
    /// restores or auto-starts a network listener from disk.
    #[default]
    SessionOnly,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RemoteGatewayConfig {
    pub mode: RemoteNetworkMode,
    pub port: u16,
    pub allow_control: bool,
}

impl Default for RemoteGatewayConfig {
    fn default() -> Self {
        Self {
            mode: RemoteNetworkMode::Off,
            port: 43821,
            allow_control: true,
        }
    }
}

impl RemoteGatewayConfig {
    pub fn restart_policy(&self) -> RemoteRestartPolicy {
        RemoteRestartPolicy::SessionOnly
    }

    fn apply_session_only_restart_policy(&mut self) {
        self.mode = RemoteNetworkMode::Off;
    }

    fn persisted_snapshot(&self) -> PersistedRemoteGatewayConfig {
        PersistedRemoteGatewayConfig {
            mode: RemoteNetworkMode::Off,
            port: self.port,
            allow_control: self.allow_control,
            restart_policy: self.restart_policy(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct PersistedRemoteGatewayConfig {
    mode: RemoteNetworkMode,
    port: u16,
    allow_control: bool,
    #[serde(default)]
    restart_policy: RemoteRestartPolicy,
}

pub struct RemoteGatewayState {
    pub config: RwLock<RemoteGatewayConfig>,
    pub auth_manager: Arc<AuthManager>,
    pub terminal_service: Arc<TerminalService>,
    pub workspace_registry: WorkspaceRegistry,
    pub event_tx: broadcast::Sender<String>,
    pub is_running: RwLock<bool>,
    pub bound_address: RwLock<Option<String>>,
    config_path: Option<PathBuf>,
}

impl RemoteGatewayState {
    pub fn new(
        terminal_service: Arc<TerminalService>,
        workspace_registry: WorkspaceRegistry,
    ) -> Self {
        Self::new_with_paths(terminal_service, workspace_registry, None, None)
    }

    pub fn new_persistent(
        terminal_service: Arc<TerminalService>,
        workspace_registry: WorkspaceRegistry,
    ) -> Self {
        let base = remote_data_dir();
        Self::new_with_paths(
            terminal_service,
            workspace_registry,
            Some(base.join("remote-config.json")),
            Some(base.join("remote-auth.json")),
        )
    }

    pub fn new_with_paths(
        terminal_service: Arc<TerminalService>,
        workspace_registry: WorkspaceRegistry,
        config_path: Option<PathBuf>,
        auth_path: Option<PathBuf>,
    ) -> Self {
        let (event_tx, _) = broadcast::channel(1024);
        let mut config = config_path
            .as_deref()
            .and_then(|path| std::fs::read(path).ok())
            .and_then(|bytes| serde_json::from_slice::<PersistedRemoteGatewayConfig>(&bytes).ok())
            .map(|persisted| RemoteGatewayConfig {
                mode: persisted.mode,
                port: persisted.port,
                allow_control: persisted.allow_control,
            })
            .unwrap_or_default();
        config.apply_session_only_restart_policy();
        Self {
            config: RwLock::new(config),
            auth_manager: Arc::new(AuthManager::with_persistence(auth_path)),
            terminal_service,
            workspace_registry,
            event_tx,
            is_running: RwLock::new(false),
            bound_address: RwLock::new(None),
            config_path,
        }
    }

    pub fn emit_event(&self, event_json: String) {
        let _ = self.event_tx.send(event_json);
    }

    pub fn persist_config(&self) -> std::io::Result<()> {
        let Some(path) = self.config_path.as_deref() else {
            return Ok(());
        };
        write_private_json(path, &self.config.read().persisted_snapshot())
    }
}

fn remote_data_dir() -> PathBuf {
    if let Some(path) = std::env::var_os("FERRYX_DATA_DIR") {
        return PathBuf::from(path).join("remote");
    }
    if let Some(home) = std::env::var_os("HOME") {
        return PathBuf::from(home).join(".ferryx").join("remote");
    }
    std::env::temp_dir().join("ferryx").join("remote")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::remote::auth::DevicePermission;
    use crate::terminal::{PtyManager, TerminalOutputHub};

    fn test_state(
        config_path: PathBuf,
        auth_path: PathBuf,
    ) -> (RemoteGatewayState, WorkspaceRegistry, Arc<TerminalService>) {
        let pty = Arc::new(PtyManager::new());
        let hub = Arc::new(TerminalOutputHub::default());
        let terminal = Arc::new(TerminalService::new(pty, hub));
        let registry = WorkspaceRegistry::new();
        let state = RemoteGatewayState::new_with_paths(
            Arc::clone(&terminal),
            registry.clone(),
            Some(config_path),
            Some(auth_path),
        );
        (state, registry, terminal)
    }

    #[test]
    fn enabled_gateway_does_not_restore_listener_after_reopen() {
        let dir = tempfile::TempDir::new().expect("tempdir");
        let config_path = dir.path().join("config.json");
        let auth_path = dir.path().join("auth.json");
        let (state, registry, terminal) = test_state(config_path.clone(), auth_path.clone());

        {
            let mut config = state.config.write();
            config.mode = RemoteNetworkMode::LocalNetwork;
            config.port = 45678;
            config.allow_control = false;
        }
        *state.is_running.write() = true;
        *state.bound_address.write() = Some("0.0.0.0:45678".into());
        let code = state
            .auth_manager
            .create_pairing_code(DevicePermission::Control);
        let (token, device) = state
            .auth_manager
            .exchange_pairing_code(&code, "Phone")
            .expect("pair");
        state.persist_config().expect("persist");

        let on_disk: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&config_path).expect("read persisted config"))
                .expect("parse persisted config");
        assert_eq!(on_disk["mode"], "off");
        assert_eq!(on_disk["port"], 45678);
        assert_eq!(on_disk["allowControl"], false);
        assert_eq!(on_disk["restartPolicy"], "sessionOnly");

        let reopened = RemoteGatewayState::new_with_paths(
            terminal,
            registry,
            Some(config_path),
            Some(auth_path),
        );
        let config = reopened.config.read().clone();
        assert_eq!(config.mode, RemoteNetworkMode::Off);
        assert_eq!(config.port, 45678);
        assert!(!config.allow_control);
        assert_eq!(config.restart_policy(), RemoteRestartPolicy::SessionOnly);
        assert!(!*reopened.is_running.read());
        assert!(reopened.bound_address.read().is_none());

        let devices = reopened.auth_manager.list_devices();
        assert_eq!(devices.len(), 1);
        assert_eq!(devices[0].id, device.id);
        assert!(reopened.auth_manager.validate_token(&token).is_ok());
    }

    #[test]
    fn stale_enabled_config_file_does_not_look_enabled() {
        let dir = tempfile::TempDir::new().expect("tempdir");
        let config_path = dir.path().join("config.json");
        let auth_path = dir.path().join("auth.json");
        std::fs::write(
            &config_path,
            r#"{"mode":"localNetwork","port":41234,"allowControl":true}"#,
        )
        .expect("write stale enabled config");

        let (state, _, _) = test_state(config_path, auth_path);
        let config = state.config.read().clone();
        assert_eq!(config.mode, RemoteNetworkMode::Off);
        assert_eq!(config.port, 41234);
        assert!(config.allow_control);
        assert_eq!(config.restart_policy(), RemoteRestartPolicy::SessionOnly);
        assert!(!*state.is_running.read());
        assert!(state.bound_address.read().is_none());
    }
}

    let active_ws = projects
        .first()
        .map(|p| p.workspace_id.clone())
        .unwrap_or_else(|| "default".into());
    let worktrees = cache.worktrees_for(&active_ws);

    let sessions = state
        .terminal_service
        .list_sessions()
        .into_iter()
        .filter_map(|id| state.terminal_service.get_session(&id))
        .map(|session| remote_terminal_session(&session, &cache))
        .collect::<Vec<_>>();

    Ok(Json(RemoteWorkspaceState {
        projects,
        active_workspace_id: active_ws,
        worktrees,
        sessions,
    }))
}

async fn create_worktree(
    State(state): State<Arc<RemoteGatewayState>>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Json(payload): Json<RemoteCreateWorktreeRequest>,
) -> Result<Json<crate::worktree::Worktree>, (StatusCode, String)> {
    let token = extract_token(&headers, Some(&query))
        .ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    let device = state
        .auth_manager
        .validate_token(&token)
        .map_err(|_| (StatusCode::UNAUTHORIZED, "Invalid or revoked token".into()))?;

    if device.permission != DevicePermission::Control {
        return Err((
            StatusCode::FORBIDDEN,
            "View-only device cannot create worktrees".into(),
        ));
    }

    let mgr = state
        .workspace_registry
        .manager(&payload.workspace_id)
        .map_err(|e| (StatusCode::BAD_REQUEST, e.to_string()))?;

    let path = mgr
        .worktree_path_for(&payload.worktree.ws_id, &payload.worktree.slug)
        .map_err(|e| (StatusCode::BAD_REQUEST, e.to_string()))?;

    let options = CreateWorktreeOptions {
        ws_id: payload.worktree.ws_id,
        slug: payload.worktree.slug,
        path,
        base_ref: payload.base_ref,
    };

    let created = mgr
        .create_worktree(options)
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;

    Ok(Json(created))
}

async fn delete_worktree(
    State(state): State<Arc<RemoteGatewayState>>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    Json(payload): Json<RemoteDeleteWorktreeRequest>,
) -> Result<StatusCode, (StatusCode, String)> {
    let token = extract_token(&headers, Some(&query))
        .ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    let device = state
        .auth_manager
        .validate_token(&token)
        .map_err(|_| (StatusCode::UNAUTHORIZED, "Invalid or revoked token".into()))?;

    if device.permission != DevicePermission::Control {
        return Err((
            StatusCode::FORBIDDEN,
            "View-only device cannot delete worktrees".into(),
        ));
    }

    let (mgr, worktree) = state
        .workspace_registry
        .resolve_worktree(&payload.workspace_id, &payload.worktree)
        .map_err(|e| (StatusCode::BAD_REQUEST, e.to_string()))?;

    mgr.delete_worktree_and_branch(&worktree.path, payload.delete_branch.unwrap_or(false))
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;

    Ok(StatusCode::NO_CONTENT)
}

async fn list_devices(
    State(state): State<Arc<RemoteGatewayState>>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
) -> Result<Json<Vec<DeviceInfo>>, (StatusCode, String)> {
    let token = extract_token(&headers, Some(&query))
        .ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    let _device = state
        .auth_manager
        .validate_token(&token)
        .map_err(|_| (StatusCode::UNAUTHORIZED, "Invalid or revoked token".into()))?;

    Ok(Json(state.auth_manager.list_devices()))
}

async fn revoke_device(
    State(state): State<Arc<RemoteGatewayState>>,
    headers: HeaderMap,
    Query(query): Query<AuthQuery>,
    AxumPath(device_id): AxumPath<String>,
) -> Result<StatusCode, (StatusCode, String)> {
    let token = extract_token(&headers, Some(&query))
        .ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    let _device = state
        .auth_manager
        .validate_token(&token)
        .map_err(|_| (StatusCode::UNAUTHORIZED, "Invalid or revoked token".into()))?;

    if state.auth_manager.revoke_device(&device_id) {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err((StatusCode::NOT_FOUND, "Device not found".into()))
    }
}

async fn ws_events_handler(
    ws: WebSocketUpgrade,
    Query(query): Query<AuthQuery>,
    headers: HeaderMap,
    State(state): State<Arc<RemoteGatewayState>>,
) -> Result<Response, (StatusCode, String)> {
    let token = extract_token(&headers, Some(&query))
        .ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    let _device = state
        .auth_manager
        .validate_token(&token)
        .map_err(|_| (StatusCode::UNAUTHORIZED, "Invalid or revoked token".into()))?;

    let rx = state.event_tx.subscribe();
    Ok(ws.on_upgrade(move |socket| handle_events_socket(socket, rx)))
}

async fn handle_events_socket(mut socket: WebSocket, mut rx: broadcast::Receiver<String>) {
    while let Ok(msg) = rx.recv().await {
        if socket.send(Message::Text(msg.into())).await.is_err() {
            break;
        }
    }
}

async fn ws_terminal_handler(
    ws: WebSocketUpgrade,
    AxumPath(session_id): AxumPath<String>,
    Query(query): Query<AuthQuery>,
    headers: HeaderMap,
    State(state): State<Arc<RemoteGatewayState>>,
) -> Result<Response, (StatusCode, String)> {
    let token = extract_token(&headers, Some(&query))
        .ok_or((StatusCode::UNAUTHORIZED, "Missing auth token".into()))?;
    let device = state
        .auth_manager
        .validate_token(&token)
        .map_err(|_| (StatusCode::UNAUTHORIZED, "Invalid or revoked token".into()))?;

    let (history, rx) = state
        .terminal_service
        .attach(&session_id)
        .map_err(|_| (StatusCode::NOT_FOUND, "Session not found".into()))?;

    Ok(ws.on_upgrade(move |socket| {
        handle_terminal_socket(socket, session_id, history, rx, device, state)
    }))
}

async fn handle_terminal_socket(
    socket: WebSocket,
    session_id: String,
    history: Vec<u8>,
    mut rx: broadcast::Receiver<Vec<u8>>,
    device: DeviceInfo,
    state: Arc<RemoteGatewayState>,
) {
    let (mut sender, mut receiver) = socket.split();

    if !history.is_empty() && sender.send(Message::Binary(history.into())).await.is_err() {
        return;
    }

    let mut send_task = tokio::spawn(async move {
        loop {
            match rx.recv().await {
                Ok(chunk) => {
                    if sender.send(Message::Binary(chunk.into())).await.is_err() {
                        break;
                    }
                }
                Err(broadcast::error::RecvError::Lagged(_)) => continue,
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    });

    let term_service = Arc::clone(&state.terminal_service);
    let session_id_clone = session_id.clone();
    let can_control = device.permission == DevicePermission::Control;

    let mut recv_task = tokio::spawn(async move {
        while let Some(Ok(msg)) = receiver.next().await {
            match msg {
                Message::Binary(bytes) => {
                    if can_control {
                        let _ = term_service.write_input(&session_id_clone, &bytes);
                    }
                }
                Message::Text(text) => {
                    if let Ok(ctrl) = serde_json::from_str::<ClientControlMessage>(&text) {
                        match ctrl {
                            ClientControlMessage::Resize { cols, rows } => {
                                let _ = term_service.resize(&session_id_clone, cols, rows);
                            }
                            ClientControlMessage::Signal { signal } => {
                                if can_control && signal == "interrupt" {
                                    let _ = term_service
                                        .signal(&session_id_clone, TerminalSignal::Interrupt);
                                }
                            }
                            ClientControlMessage::Ping => {}
                        }
                    }
                }
                Message::Close(_) => break,
                _ => {}
            }
        }
    });

    tokio::select! {
        _ = (&mut send_task) => recv_task.abort(),
        _ = (&mut recv_task) => send_task.abort(),
    };
}

fn resolve_dist_dir() -> PathBuf {
    let mut candidates = vec![
        PathBuf::from("ui/dist"),
        PathBuf::from("../ui/dist"),
        PathBuf::from("../../ui/dist"),
    ];
    if let Ok(cwd) = std::env::current_dir() {
        candidates.push(cwd.join("ui/dist"));
        candidates.push(cwd.join("dist"));
    }
    if let Ok(exe) = std::env::current_exe() {
        let mut cur = exe;
        for _ in 0..6 {
            if let Some(parent) = cur.parent() {
                candidates.push(parent.join("ui/dist"));
                candidates.push(parent.join("Resources/ui/dist"));
                candidates.push(parent.join("../Resources/ui/dist"));
                candidates.push(parent.join("../Resources"));
                cur = parent.to_path_buf();
            }
        }
    }
    for c in &candidates {
        if c.exists() && c.is_dir() && c.join("index.html").exists() {
            return c.clone();
        }
    }
    PathBuf::from("ui/dist")
}

async fn serve_static_or_index(uri: axum::http::Uri) -> Response {
    let dist_dir = resolve_dist_dir();
    let path = uri.path().trim_start_matches('/');
    let file_path = dist_dir.join(path);

    if !path.is_empty() && file_path.exists() && file_path.is_file() {
        if let Ok(bytes) = tokio::fs::read(&file_path).await {
            let mime = mime_guess::from_path(&file_path).first_or_octet_stream();
            return ([(header::CONTENT_TYPE, mime.as_ref())], bytes).into_response();
        }
    }

    // SPA fallback: serve index.html from dist_dir
    let index_file = dist_dir.join("index.html");
    if index_file.exists() && index_file.is_file() {
        if let Ok(html) = tokio::fs::read_to_string(&index_file).await {
            return Html(html).into_response();
        }
    }

    Html(EMBEDDED_FALLBACK_HTML).into_response()
}

